# -*- coding: utf-8 -*-
"""
Complete 13-language localization catalog for V-Stream Downloader Pro.
Covers all `t(key)` entries, all static `tp(ar, en)` phrases, all 32 theme palette names,
all 8 home showcase cards, and all dynamic f-string `tp(...)` templates across:
Arabic (ar), English (en), Spanish (es), French (fr), German (de), Russian (ru),
Turkish (tr), Urdu (ur), Persian (fa), Indonesian (id), Malay (ms), Bengali (bn), Greek (el).
"""
import re
from typing import Callable, Dict, List, Tuple

# 11 additional languages beyond 'ar' and 'en':
# Order inside compact 11-tuples: (es, fr, de, ru, tr, ur, fa, id, ms, bn, el)
LANG_ORDER: Tuple[str, ...] = ("es", "fr", "de", "ru", "tr", "ur", "fa", "id", "ms", "bn", "el")


def _expand_11(rows: Dict[str, Tuple[str, ...]]) -> Dict[str, Dict[str, str]]:
    """Converts {key: (es, fr, de, ru, tr, ur, fa, id, ms, bn, el)} into {lang: {key: val}}."""
    out: Dict[str, Dict[str, str]] = {lang: {} for lang in LANG_ORDER}
    for key, vals in rows.items():
        for idx, lang in enumerate(LANG_ORDER):
            if idx < len(vals):
                out[lang][key] = vals[idx]
    return out


