        "HTTP 429 بہت زیادہ درخواستیں — تھوڑا انتظار کریں یا سیٹنگز میں کوکیز/پراکسی فعال کریں۔",
        "خطای HTTP 429 (تعداد درخواست زیاد) — کمی صبر کنید یا کوکی/پروکسی را در تنظیمات فعال کنید.",
        "HTTP 429 Terlalu Banyak Permintaan — tunggu sebentar atau aktifkan Cookie/Proxy di Pengaturan.",
        "HTTP 429 Terlalu Banyak Permintaan — tunggu sebentar atau aktifkan Kuki/Proksi dalam Tetapan.",
        "HTTP 429 অতিরিক্ত অনুরোধ — কিছুক্ষণ অপেক্ষা করুন অথবা সেটিংসে কুকিজ/প্রক্সি চালু করুন।",
        "HTTP 429 Πάρα πολλά αιτήματα — περιμένετε λίγο ή ενεργοποιήστε Cookies/Proxy στις Ρυθμίσεις.",
