def translate_phrase(ar_text: str, en_text: str, lang: str) -> str:
    """
    Translates any static or dynamic `tp(ar_text, en_text)` call into the active `lang`
    across all 13 supported UI languages (`ar`, `en`, `es`, `fr`, `de`, `ru`, `tr`, `ur`, `fa`, `id`, `ms`, `bn`, `el`).
    """
    if lang == "ar":
        return ar_text
    if lang == "en":
        return en_text

    # 1. Exact static lookup
    lang_map = STATIC_PHRASE_TRANSLATIONS.get(lang)
    if lang_map:
        hit = lang_map.get(en_text)
        if hit is not None:
            return hit

    # 2. Dynamic regex pattern lookup
    for regex, tpl_by_lang in _DYNAMIC_PATTERNS:
        m = regex.match(en_text)
        if m:
            lang_tpl_dict = tpl_by_lang.get(lang)
            if lang_tpl_dict and "tpl" in lang_tpl_dict:
                try:
                    return lang_tpl_dict["tpl"].format(*m.groups())
                except Exception:
                    return en_text

    # Fallback if a custom string was passed
    return ar_text if lang in ("ur", "fa") else en_text
